using Ticket = std::array<unsigned char, 16>;

struct Admission {
    std::uint64_t player;
    std::uint64_t epoch;
};

private:
    struct Entry {
        Ticket ticket;
        Admission admission;
        Clock::time_point expires;
    };

    std::mutex mutex_;
    std::array<std::optional<Entry>, Capacity> slots_{};

inline std::optional<Ticket> new_ticket(RandomBytes random=RAND_bytes) {
    Ticket ticket{};
    if(!random || random(ticket.data(),static_cast<int>(ticket.size()))!=1)return std::nullopt;
    return ticket;
}

inline std::string ticket_text(const Ticket& ticket) {
    return std::string(kTicketPrefix)+hex_bytes(ticket.data(),ticket.size());
}
inline std::optional<Ticket> parse_ticket(const std::string& text) {
    Ticket ticket{};
    if(text.size()!=kTicketPrefix.size()+ticket.size()*2 ||
       text.compare(0,kTicketPrefix.size(),kTicketPrefix.data(),kTicketPrefix.size())!=0)return std::nullopt;
    const auto hex=text.substr(kTicketPrefix.size());
    if(!credential_hex(hex,ticket.size()*2))return std::nullopt;
    auto nibble=[](char c)->unsigned char{return static_cast<unsigned char>(c<='9'?c-'0':c-'a'+10);};
    for(std::size_t i=0;i<ticket.size();++i)
        ticket[i]=static_cast<unsigned char>((nibble(hex[i*2])<<4)|nibble(hex[i*2+1]));
    return ticket;
}

if (admission.player == 0) return IssueTicket::invalid;
if (lifetime <= Clock::duration::zero()) return IssueTicket::invalid;
if (now > Clock::time_point::max() - lifetime) return IssueTicket::invalid;

std::lock_guard<std::mutex> lock(mutex_);

// Drop entries that are already expired at `now` (expires <= now).
for (auto& slot : slots_) {
    if (slot.has_value() && slot->expires <= now) slot.reset();
}

// Reject any surviving entry carrying the same opaque ticket bytes.
for (const auto& slot : slots_) {
    if (slot.has_value() && slot->ticket == ticket) {
        return IssueTicket::collision;
    }
}

std::size_t target = Capacity;
for (std::size_t i = 0; i < Capacity; ++i) {
    if (!slots_[i].has_value()) {
        if (target == Capacity) target = i; // first free slot
    } else if (slots_[i]->admission.player == admission.player) {
        target = i; // replacement wins over a free slot
        break;
    }
}
if (target == Capacity) return IssueTicket::full;

// Commit only after every rejection check has passed.
slots_[target] = Entry{ticket, admission, now + lifetime};
return IssueTicket::issued;

std::optional<Admission> consume(const Ticket& ticket, Clock::time_point now) {
    std::lock_guard<std::mutex> lock(mutex_);

    for (auto& slot : slots_) {
        if (!slot.has_value() || slot->ticket != ticket) continue;

        const Admission value = slot->admission;
        const Clock::time_point expires = slot->expires;
        slot.reset(); // single use: never restore or hand out a reference
        if (expires <= now) return std::nullopt;
        return value;
    }
    return std::nullopt;
}

auto redeemed=store.consume(*second,now);
if(!redeemed||redeemed->player!=account.player||redeemed->epoch!=account.epoch)return 5;
// Simulate losing the successful response. A retry cannot redeem it again.
if(store.consume(*second,now))return 6;
